// Converts docs/design/tokens.json (the single source of design values) into:
//   src/generated/tokens.css  – CSS custom properties (--sf-*) for light + dark
//   src/generated/theme.css   – Tailwind v4 @theme that maps utilities to those variables
//   src/generated/tokens.ts   – typed token names/values for TS code (charts, tests)
// Run: pnpm --filter @serviceflow/ui-tokens gen   (never edit the generated files by hand)
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const SOURCE = resolve(here, '../../../docs/design/tokens.json');
const OUT_DIR = resolve(here, '../src/generated');
const HEADER =
  '/* GENERATED by packages/ui-tokens/scripts/build.mjs from docs/design/tokens.json — do not edit */';

const tokens = JSON.parse(readFileSync(SOURCE, 'utf8'));
const errors = [];
const fail = (msg) => errors.push(msg);

// ---------- validate ----------
const HEX = /^#[0-9A-Fa-f]{6}$/;
const REF = /^\{([a-z0-9-]+)\}$/;
const NAME = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const themeIds = tokens.color.themes.map((t) => t.id);
if (!themeIds.includes('light')) fail('color.themes must include "light"');

const colorNames = new Set();
for (const t of tokens.color.tokens) {
  if (!NAME.test(t.name)) fail(`color "${t.name}": name must be kebab-case`);
  if (colorNames.has(t.name)) fail(`color "${t.name}": duplicate name`);
  colorNames.add(t.name);
  for (const id of themeIds) {
    const v = t.value[id];
    if (v === undefined) fail(`color "${t.name}": missing value for theme "${id}"`);
    else if (!HEX.test(v) && !REF.test(v))
      fail(`color "${t.name}" (${id}): "${v}" is not #RRGGBB or {ref}`);
  }
}
for (const t of tokens.color.tokens) {
  for (const id of themeIds) {
    const m = REF.exec(t.value[id] ?? '');
    if (m && !colorNames.has(m[1])) fail(`color "${t.name}" (${id}): unknown reference {${m[1]}}`);
  }
}
// Tailwind's default spacing is 4px per step; the tokens must agree so `p-4` == space-4.
for (const [name, value] of Object.entries(tokens.spacing)) {
  const step = Number(name.replace('space-', ''));
  if (`${step * 4}px` !== value)
    fail(`spacing "${name}" = ${value}, expected ${step * 4}px (4px grid)`);
}
for (const s of tokens.type.styles) {
  if (s.family && !tokens.type.families[s.family])
    fail(`type "${s.name}": unknown family "${s.family}"`);
}
if (errors.length) {
  console.error(`tokens.json is invalid:\n  - ${errors.join('\n  - ')}`);
  process.exit(1);
}

// ---------- helpers ----------
const colorVar = (name) => `--sf-color-${name}`;
const resolveColor = (value) => {
  const m = REF.exec(value);
  return m ? `var(${colorVar(m[1])})` : value.toUpperCase();
};
const block = (selector, lines) => `${selector} {\n${lines.map((l) => `  ${l}`).join('\n')}\n}`;

// ---------- tokens.css ----------
const lightVars = [];
const darkVars = [];
for (const t of tokens.color.tokens) {
  lightVars.push(`${colorVar(t.name)}: ${resolveColor(t.value.light)};`);
  if (t.value.dark) darkVars.push(`${colorVar(t.name)}: ${resolveColor(t.value.dark)};`);
}
for (const [name, value] of Object.entries(tokens.type.families))
  lightVars.push(`--sf-font-${name}: ${value};`);
for (const [name, value] of Object.entries(tokens.radius))
  lightVars.push(`--sf-${name}: ${value};`);
for (const [name, value] of Object.entries(tokens.shadow)) {
  lightVars.push(`--sf-${name}: ${value.light};`);
  if (value.dark) darkVars.push(`--sf-${name}: ${value.dark};`);
}
for (const [name, value] of Object.entries(tokens.layout))
  lightVars.push(`--sf-layout-${name}: ${value};`);

const tokensCss = [
  HEADER,
  block(':root', ['color-scheme: light;', ...lightVars]),
  // Dark values exist in tokens.json; the designs are light-only, so dark is opt-in via data-theme.
  block(':root[data-theme="dark"]', ['color-scheme: dark;', ...darkVars]),
  '',
].join('\n\n');

// ---------- theme.css (Tailwind v4) ----------
const themeLines = [
  // Remove Tailwind's built-in palette: only ServiceFlow tokens can be used (no bg-blue-500, no raw hex).
  '--color-*: initial;',
  ...tokens.color.tokens.map((t) => `--color-${t.name}: var(${colorVar(t.name)});`),
  '',
  '--font-*: initial;',
  // --sf-font-*-face is set by next/font in each app's root layout (self-hosted font files).
  ...Object.keys(tokens.type.families).map(
    (n) => `--font-${n}: var(--sf-font-${n}-face, ${tokens.type.families[n]});`,
  ),
  '',
  '--text-*: initial;',
  ...tokens.type.styles.flatMap((s) => [
    `--text-${s.name}: ${s.fontSize};`,
    `--text-${s.name}--line-height: ${s.lineHeight};`,
    `--text-${s.name}--font-weight: ${s.fontWeight};`,
  ]),
  '',
  '--radius-*: initial;',
  ...Object.keys(tokens.radius).map((n) => `--${n}: var(--sf-${n});`),
  '',
  '--shadow-*: initial;',
  ...Object.keys(tokens.shadow).map((n) => `--${n}: var(--sf-${n});`),
  '',
  // Layout sizes as spacing keys: w-sidebar, h-topbar, min-h-touch, h-badge, max-w-content
  '--spacing-sidebar: var(--sf-layout-sidebar-width);',
  '--spacing-topbar: var(--sf-layout-topbar-height);',
  '--spacing-touch: var(--sf-layout-touch-target-min);',
  '--spacing-badge: var(--sf-layout-badge-height);',
  '--container-content: var(--sf-layout-content-max);',
  '--container-mobile: var(--sf-layout-mobile-design-width);',
];
const themeCss = [HEADER, block('@theme inline', themeLines), ''].join('\n\n');

// ---------- tokens.ts ----------
const colorEntries = tokens.color.tokens
  .map((t) => `  '${t.name}': 'var(${colorVar(t.name)})',`)
  .join('\n');
// Resolved light-theme hex values, for places that cannot use CSS variables (PWA manifest, emails).
const resolveHex = (name, seen = new Set()) => {
  if (seen.has(name)) throw new Error(`circular color reference: ${name}`);
  seen.add(name);
  const value = tokens.color.tokens.find((t) => t.name === name).value.light;
  const m = REF.exec(value);
  return m ? resolveHex(m[1], seen) : value.toUpperCase();
};
const hexEntries = tokens.color.tokens
  .map((t) => `  '${t.name}': '${resolveHex(t.name)}',`)
  .join('\n');

const tokensTs = `${HEADER.replace('/*', '//').replace(' */', '')}
/** CSS variable reference for every color token, e.g. for chart libraries that need a color string. */
export const colorVars = {
${colorEntries}
} as const;

export type ColorToken = keyof typeof colorVars;

/** Light-theme hex values. Only for non-CSS contexts (manifest, emails) — UI code uses classes/vars. */
export const colorHex = {
${hexEntries}
} as const satisfies Record<ColorToken, string>;

export const layout = ${JSON.stringify(tokens.layout, null, 2)} as const;

export const typeStyles = ${JSON.stringify(
  Object.fromEntries(
    tokens.type.styles.map((s) => [
      s.name,
      {
        fontSize: s.fontSize,
        lineHeight: s.lineHeight,
        fontWeight: s.fontWeight,
        ...(s.family ? { family: s.family } : {}),
      },
    ]),
  ),
  null,
  2,
)} as const;

export type TypeStyle = keyof typeof typeStyles;
`;

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(resolve(OUT_DIR, 'tokens.css'), tokensCss);
writeFileSync(resolve(OUT_DIR, 'theme.css'), themeCss);
writeFileSync(resolve(OUT_DIR, 'tokens.ts'), tokensTs);
console.log(
  `ui-tokens: ${tokens.color.tokens.length} colors, ${tokens.type.styles.length} type styles → src/generated/`,
);
